#include <memory>
#include <iostream>

class Resource {};

int main() {
    std::auto_ptr<Resource> p1(new Resource);
    std::cout << "p1 owns resource: " << (p1.get() != nullptr) << std::endl;

    std::auto_ptr<Resource> p2 = p1; // Ownership transfer (destructive copy)

    std::cout << "p2 owns resource: " << (p2.get() != nullptr) << std::endl;
    std::cout << "p1 owns resource now: " << (p1.get() != nullptr) << std::endl;
    // p1.get() is now NULL
    // *p1; // DANGER: Dereferencing null pointer
}
